// ===== Data Validation =====

// Check if dataset is empty
if (items.length === 0) {
  throw new Error("Dataset is empty.");
}

// Required columns
const requiredColumns = [
  "OrderID",
  "Date",
  "Region",
  "Product",
  "Salesperson",
  "Quantity",
  "UnitPrice",
  "Revenue",
  "Profit",
  "Channel"
];

const errors = [];

for (let i = 0; i < items.length; i++) {

  const row = items[i].json;

  // Check required columns
  for (const col of requiredColumns) {
    if (!(col in row)) {
      errors.push(`Row ${i + 1}: Missing column '${col}'`);
    }
  }

  // Check for empty values
  for (const col of requiredColumns) {
    if (row[col] === "" || row[col] === null || row[col] === undefined) {
      errors.push(`Row ${i + 1}: '${col}' is empty`);
    }
  }

  // Revenue must be numeric
  if (isNaN(Number(row.Revenue))) {
    errors.push(`Row ${i + 1}: Revenue is not numeric`);
  }

  // Quantity must be positive
  if (Number(row.Quantity) <= 0) {
    errors.push(`Row ${i + 1}: Invalid Quantity`);
  }
}

// Stop workflow if validation fails
if (errors.length > 0) {
  throw new Error(errors.join("\n"));
}

// Pass original dataset to next node
return items;

const data = $('Aggregate').first().json.data;

let totalRevenue = 0;
let totalProfit = 0;
let totalOrders = data.length;
let totalQuantity = 0;

for (const row of data) {
  totalRevenue += Number(row.Revenue || 0);
  totalProfit += Number(row.Profit || 0);
  totalQuantity += Number(row.Quantity || 0);
}

const avgRevenue = totalRevenue / totalOrders;

return [
{
json:{
totalOrders,
totalRevenue,
totalProfit,
totalQuantity,
averageRevenuePerOrder: Number(avgRevenue.toFixed(2))
}
}
];

const rows = $input.first().json.data;

const regionRevenue = {};
const productRevenue = {};
const monthlyRevenue = {};
const channelRevenue = {};
const salespersonRevenue = {};

let totalRevenue = 0;
let totalProfit = 0;
let totalOrders = rows.length;

for (const row of rows) {

  const revenue = Number(row.Revenue);
  const profit = Number(row.Profit);

  totalRevenue += revenue;
  totalProfit += profit;

  // Region
  regionRevenue[row.Region] = (regionRevenue[row.Region] || 0) + revenue;

  // Product
  productRevenue[row.Product] = (productRevenue[row.Product] || 0) + revenue;

  // Channel
  channelRevenue[row.Channel] = (channelRevenue[row.Channel] || 0) + revenue;

  // Salesperson
  salespersonRevenue[row.Salesperson] =
    (salespersonRevenue[row.Salesperson] || 0) + revenue;

  // Month
  const month = row.Date.substring(0,7);
  monthlyRevenue[month] = (monthlyRevenue[month] || 0) + revenue;
}

return [{
  json:{
    totalRevenue,
    totalProfit,
    totalOrders,

    regionRevenue,
    productRevenue,
    monthlyRevenue,
    channelRevenue,
    salespersonRevenue
  }
}];
